import React, { useState } from 'react'
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react'
import '@testing-library/jest-dom'
import { autoUpdate } from '@floating-ui/dom'
import { TooltipController } from '../components/TooltipController'
import {
  advanceTimers,
  flushMicrotasks,
  flushPendingTimers,
  hoverAnchor,
  unhoverAnchor,
  waitForTooltip,
  waitForTooltipToStopShowing,
} from './test-utils'

jest.mock('@floating-ui/dom', () => {
  const originalModule = jest.requireActual('@floating-ui/dom')
  return {
    ...originalModule,
    autoUpdate: jest.fn().mockImplementation((reference, floating, update) => {
      if (update) update()
      return jest.fn()
    }),
  }
})

describe('tooltip interaction behavior', () => {
  beforeEach(() => {
    jest.useFakeTimers()
    jest.clearAllMocks()
  })

  afterEach(() => {
    flushPendingTimers()
    jest.useRealTimers()
  })

  const renderAndFlush = async (ui) => {
    let view
    await act(async () => {
      view = render(ui)
      await Promise.resolve()
    })
    return view
  }

  test('opens on click when click is the configured trigger', async () => {
    await renderAndFlush(
      <>
        <span data-tooltip-id="click-only-test">Hover Me</span>
        <TooltipController
          id="click-only-test"
          content="Click Only Test"
          openEvents={{ click: true }}
          closeEvents={{ click: true }}
        />
      </>,
    )

    const anchor = screen.getByText('Hover Me')

    hoverAnchor(anchor, 100)
    expect(document.getElementById('click-only-test')).not.toBeInTheDocument()

    fireEvent.click(anchor)
    await flushMicrotasks()
    const tooltip = await waitForTooltip('click-only-test')
    expect(tooltip).toHaveTextContent('Click Only Test')
  })

  test('stops showing after scroll and resize global close events', async () => {
    await renderAndFlush(
      <>
        <span data-tooltip-id="global-events-test">Hover Me</span>
        <TooltipController
          id="global-events-test"
          content="Global Events Test"
          globalCloseEvents={{ scroll: true, resize: true }}
        />
      </>,
    )

    const anchor = screen.getByText('Hover Me')

    hoverAnchor(anchor, 1000)
    await waitForTooltip('global-events-test')

    fireEvent.scroll(window)
    advanceTimers(100)
    await flushMicrotasks()
    await waitForTooltipToStopShowing('global-events-test')

    // Allow the tooltip to fully unmount before re-hovering
    advanceTimers(100)
    await flushMicrotasks()

    hoverAnchor(anchor, 1000)
    await flushMicrotasks()
    await waitForTooltip('global-events-test')

    fireEvent.resize(window)
    advanceTimers(100)
    await flushMicrotasks()
    await waitForTooltipToStopShowing('global-events-test')
  })

  test('keeps a clickable tooltip open while the pointer moves into it', async () => {
    await renderAndFlush(
      <>
        <span data-tooltip-id="clickable-test">Hover Me</span>
        <TooltipController
          id="clickable-test"
          content="Clickable Test"
          clickable
          globalCloseEvents={{ scroll: true, resize: true }}
        />
      </>,
    )

    const anchor = screen.getByText('Hover Me')

    hoverAnchor(anchor, 1000)
    const tooltip = await waitForTooltip('clickable-test')

    unhoverAnchor(anchor, 0)
    fireEvent.mouseEnter(tooltip)
    advanceTimers(150) // past clickable's 100ms hide-delay so the close timer fires
    await flushMicrotasks()

    const elem = screen.getByRole('tooltip')
    expect(elem).toBeInTheDocument()
    expect(elem).toHaveClass('react-tooltip__show')

    fireEvent.mouseLeave(tooltip)
    await flushMicrotasks()
    await waitForTooltipToStopShowing('clickable-test')
  })

  test('keeps autoUpdate wired when an active anchor is removed', async () => {
    const RemovableTest = () => {
      const [showAnchor, setShowAnchor] = useState(true)

      return (
        <div>
          {showAnchor && <span data-tooltip-id="removable-test">Hover Me</span>}
          <button onClick={() => setShowAnchor(false)}>Remove Anchor</button>
          <TooltipController id="removable-test" content="Removable Test" />
        </div>
      )
    }

    await renderAndFlush(<RemovableTest />)

    const anchor = screen.getByText('Hover Me')
    hoverAnchor(anchor, 500)
    await waitForTooltip('removable-test')

    fireEvent.click(screen.getByText('Remove Anchor'))
    await flushMicrotasks()

    await waitFor(() => {
      expect(screen.queryByText('Hover Me')).not.toBeInTheDocument()
    })
    expect(autoUpdate).toHaveBeenCalled()
  })

  test('opens without emitting runtime errors', async () => {
    const consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {})

    await renderAndFlush(
      <>
        <span data-tooltip-id="console-error-test">Hover Me</span>
        <TooltipController id="console-error-test" content="Console Error Test" />
      </>,
    )

    hoverAnchor(screen.getByText('Hover Me'), 500)
    await flushMicrotasks()

    expect(screen.getByText('Console Error Test')).toBeInTheDocument()
    consoleErrorSpy.mockRestore()
  })

  test('ignores missing pointermove events in float mode', () => {
    const originalAddEventListener = HTMLSpanElement.prototype.addEventListener
    const listenerRegistry = []

    const addEventListenerSpy = jest
      .spyOn(HTMLSpanElement.prototype, 'addEventListener')
      .mockImplementation(function mockAddEventListener(event, listener, options) {
        listenerRegistry.push({ target: this, event, listener })
        return originalAddEventListener.call(this, event, listener, options)
      })

    render(
      <>
        <span data-tooltip-id="float-guard-test">Hover Me</span>
        <TooltipController id="float-guard-test" content="Float Guard Test" float />
      </>,
    )

    const pointerMoveListener = listenerRegistry.find(
      ({ target, event }) => target.textContent === 'Hover Me' && event === 'pointermove',
    )?.listener

    expect(() => {
      act(() => {
        pointerMoveListener?.()
      })
    }).not.toThrow()

    addEventListenerSpy.mockRestore()
  })

  test('ignores missing open events before an anchor is resolved', () => {
    const originalAddEventListener = HTMLSpanElement.prototype.addEventListener
    const listenerRegistry = []

    const addEventListenerSpy = jest
      .spyOn(HTMLSpanElement.prototype, 'addEventListener')
      .mockImplementation(function mockAddEventListener(event, listener, options) {
        listenerRegistry.push({ target: this, event, listener })
        return originalAddEventListener.call(this, event, listener, options)
      })

    render(
      <>
        <span data-tooltip-id="missing-open-event-test">Hover Me</span>
        <TooltipController id="missing-open-event-test" content="Missing Open Event Test" />
      </>,
    )

    const mouseEnterListener = listenerRegistry.find(
      ({ target, event }) => target.textContent === 'Hover Me' && event === 'mouseenter',
    )?.listener

    expect(() => {
      act(() => {
        mouseEnterListener?.()
      })
      advanceTimers(60)
    }).not.toThrow()
    expect(document.getElementById('missing-open-event-test')).not.toBeInTheDocument()

    addEventListenerSpy.mockRestore()
  })

  test('ignores disconnected anchors during open handling', () => {
    const originalAddEventListener = window.EventTarget.prototype.addEventListener
    const listenerRegistry = []

    const addEventListenerSpy = jest
      .spyOn(window.EventTarget.prototype, 'addEventListener')
      .mockImplementation(function mockAddEventListener(event, listener, options) {
        listenerRegistry.push({ target: this, event, listener })
        return originalAddEventListener.call(this, event, listener, options)
      })

    render(
      <>
        <span data-tooltip-id="anchor-guards-test">Hover Me</span>
        <TooltipController id="anchor-guards-test" content="Anchor Guards Test" />
      </>,
    )

    const mouseOverListener = listenerRegistry.find(
      ({ target, event }) => target === document && event === 'mouseover',
    )?.listener
    expect(mouseOverListener).toBeDefined()

    const detachedAnchor = document.createElement('span')
    detachedAnchor.textContent = 'Detached Anchor'

    act(() => {
      mouseOverListener({
        target: detachedAnchor,
        relatedTarget: null,
      })
    })
    advanceTimers(60)

    expect(document.getElementById('anchor-guards-test')).not.toBeInTheDocument()

    addEventListenerSpy.mockRestore()
  })
})

/**
 * Shared document event delegation.
 *
 * Instead of N tooltips each calling document.addEventListener(type, handler),
 * we maintain ONE document listener per event type. When the event fires,
 * we iterate through all registered handlers for that type.
 *
 * This reduces document-level listeners from O(N × eventTypes) to O(eventTypes).
 */

type Handler = (event: Event) => void

const handlersByType = new Map<string, Set<Handler>>()

function getOrCreateSet(eventType: string): Set<Handler> {
  let set = handlersByType.get(eventType)
  if (!set) {
    set = new Set()
    handlersByType.set(eventType, set)
    document.addEventListener(eventType, dispatch)
  }
  return set
}

function dispatch(event: Event): void {
  const handlers = handlersByType.get(event.type)
  if (handlers) {
    // Safe to iterate directly — mutations (add/remove) only happen in
    // setup/cleanup, not during dispatch. Set iteration is stable for
    // entries that existed when iteration began.
    handlers.forEach((handler) => {
      handler(event)
    })
  }
}

/**
 * Register a handler for a document-level event type.
 * Returns an unsubscribe function.
 */
export function addDelegatedEventListener(eventType: string, handler: Handler): () => void {
  const set = getOrCreateSet(eventType)
  set.add(handler)

  return () => {
    set.delete(handler)
    if (set.size === 0) {
      handlersByType.delete(eventType)
      document.removeEventListener(eventType, dispatch)
    }
  }
}

/**
 * Reset for testing purposes.
 */
export function resetEventDelegation(): void {
  handlersByType.forEach((_handlers, eventType) => {
    document.removeEventListener(eventType, dispatch)
  })
  handlersByType.clear()
}
import { useEffect, useMemo, useRef } from 'react'
import type { RefObject } from 'react'
import { autoUpdate } from '@floating-ui/dom'
import {
  debounce,
  getScrollParent,
  clearTimeoutRef,
  parseDataTooltipIdSelector,
  resolveDataTooltipAnchor,
} from '../../utils'
import type {
  AnchorCloseEvents,
  AnchorOpenEvents,
  GlobalCloseEvents,
  IPosition,
} from './TooltipTypes'
import { addDelegatedEventListener } from './event-delegation'

const useTooltipEvents = ({
  activeAnchor,
  anchorElements,
  anchorSelector,
  clickable,
  closeEvents,
  delayHide,
  delayShow,
  disableTooltip,
  float,
  globalCloseEvents,
  handleHideTooltipDelayed,
  handleShow,
  handleShowTooltipDelayed,
  handleTooltipPosition,
  hoveringTooltip,
  imperativeModeOnly,
  lastFloatPosition,
  openEvents,
  openOnClick,
  rendered,
  setActiveAnchor,
  show,
  tooltipHideDelayTimerRef,
  tooltipRef,
  tooltipShowDelayTimerRef,
  updateTooltipPosition,
}: {
  activeAnchor: HTMLElement | null
  anchorElements: HTMLElement[]
  anchorSelector: string
  clickable: boolean
  closeEvents?: AnchorCloseEvents
  delayHide: number
  delayShow: number
  disableTooltip?: (anchorRef: HTMLElement | null) => boolean
  float: boolean
  globalCloseEvents?: GlobalCloseEvents
  handleHideTooltipDelayed: (delay?: number) => void
  handleShow: (value: boolean) => void
  handleShowTooltipDelayed: (delay?: number) => void
  handleTooltipPosition: ({ x, y }: IPosition) => void
  hoveringTooltip: RefObject<boolean>
  imperativeModeOnly?: boolean
  lastFloatPosition: RefObject<IPosition | null>
  openEvents?: AnchorOpenEvents
  openOnClick: boolean
  rendered: boolean
  setActiveAnchor: (anchor: HTMLElement | null) => void
  show: boolean
  tooltipHideDelayTimerRef: RefObject<NodeJS.Timeout | null>
  tooltipRef: RefObject<HTMLElement | null>
  tooltipShowDelayTimerRef: RefObject<NodeJS.Timeout | null>
  updateTooltipPosition: () => void
}) => {
  // Ref-stable debounced handlers — avoids recreating debounce instances on every effect run
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const debouncedShowRef = useRef(debounce((_anchor: HTMLElement | null) => {}, 50, true))
  const debouncedHideRef = useRef(debounce(() => {}, 50, true))

  // Cache scroll parents — only recompute when the element actually changes
  const anchorScrollParentRef = useRef<Element | null>(null)
  const tooltipScrollParentRef = useRef<Element | null>(null)
  const prevAnchorRef = useRef<HTMLElement | null>(null)
  const prevTooltipRef = useRef<HTMLElement | null>(null)

  if (activeAnchor !== prevAnchorRef.current) {
    prevAnchorRef.current = activeAnchor
    anchorScrollParentRef.current = getScrollParent(activeAnchor)
  }
  const currentTooltipEl = tooltipRef.current
  if (currentTooltipEl !== prevTooltipRef.current) {
    prevTooltipRef.current = currentTooltipEl
    tooltipScrollParentRef.current = getScrollParent(currentTooltipEl)
  }

  // Memoize event config objects — only rebuild when the relevant props change
  const hasClickEvent =
    openOnClick || openEvents?.click || openEvents?.dblclick || openEvents?.mousedown
  const actualOpenEvents: AnchorOpenEvents = useMemo(() => {
    const events: AnchorOpenEvents = openEvents
      ? { ...openEvents }
      : {
          mouseenter: true,
          focus: true,
          click: false,
          dblclick: false,
          mousedown: false,
        }
    if (!openEvents && openOnClick) {
      Object.assign(events, {
        mouseenter: false,
        focus: false,
        click: true,
      })
    }
    if (imperativeModeOnly) {
      Object.assign(events, {
        mouseenter: false,
        focus: false,
        click: false,
        dblclick: false,
        mousedown: false,
      })
    }
    return events
  }, [openEvents, openOnClick, imperativeModeOnly])

  const actualCloseEvents: AnchorCloseEvents = useMemo(() => {
    const events: AnchorCloseEvents = closeEvents
      ? { ...closeEvents }
      : {
          mouseleave: true,
          blur: true,
          click: false,
          dblclick: false,
          mouseup: false,
        }
    if (!closeEvents && openOnClick) {
      Object.assign(events, {
        mouseleave: false,
        blur: false,
      })
    }
    if (imperativeModeOnly) {
      Object.assign(events, {
        mouseleave: false,
        blur: false,
        click: false,
        dblclick: false,
        mouseup: false,
      })
    }
    return events
  }, [closeEvents, openOnClick, imperativeModeOnly])

  const actualGlobalCloseEvents: GlobalCloseEvents = useMemo(() => {
    const events: GlobalCloseEvents = globalCloseEvents
      ? { ...globalCloseEvents }
      : {
          escape: false,
          scroll: false,
          resize: false,
          clickOutsideAnchor: hasClickEvent || false,
        }
    if (imperativeModeOnly) {
      Object.assign(events, {
        escape: false,
        scroll: false,
        resize: false,
        clickOutsideAnchor: false,
      })
    }
    return events
  }, [globalCloseEvents, hasClickEvent, imperativeModeOnly])

  // --- Refs for values read inside event handlers (avoids effect deps) ---
  const activeAnchorRef = useRef(activeAnchor)
  activeAnchorRef.current = activeAnchor
  const showRef = useRef(show)
  showRef.current = show
  const anchorElementsRef = useRef(anchorElements)
  anchorElementsRef.current = anchorElements
  const handleShowRef = useRef(handleShow)
  handleShowRef.current = handleShow
  const handleTooltipPositionRef = useRef(handleTooltipPosition)
  handleTooltipPositionRef.current = handleTooltipPosition
  const updateTooltipPositionRef = useRef(updateTooltipPosition)
  updateTooltipPositionRef.current = updateTooltipPosition

  // --- Handler refs (updated every render, read via ref indirection in effects) ---
  const resolveAnchorElementRef = useRef<(target: EventTarget | null) => HTMLElement | null>(
    () => null,
  )
  const handleShowTooltipRef = useRef<(anchor: HTMLElement | null) => void>(() => {})
  const handleHideTooltipRef = useRef<() => void>(() => {})

  const dataTooltipId = anchorSelector ? parseDataTooltipIdSelector(anchorSelector) : null

  resolveAnchorElementRef.current = (target: EventTarget | null) => {
    const targetElement = target as HTMLElement | null

    if (!targetElement?.isConnected) {
      return null
    }

    if (dataTooltipId) {
      const matchedAnchor = resolveDataTooltipAnchor(targetElement, dataTooltipId)

      if (matchedAnchor && !disableTooltip?.(matchedAnchor)) {
        return matchedAnchor
      }

    if (!targetElement?.isConnected) {
      return null
    }

    if (dataTooltipId) {
      const matchedAnchor = resolveDataTooltipAnchor(targetElement, dataTooltipId)

      if (matchedAnchor && !disableTooltip?.(matchedAnchor)) {
        return matchedAnchor
      }
    } else if (anchorSelector) {
      try {
        const matchedAnchor =
          (targetElement.matches(anchorSelector)
            ? targetElement
            : targetElement.closest(anchorSelector)) ?? null

        if (matchedAnchor && !disableTooltip?.(matchedAnchor as HTMLElement)) {
          return matchedAnchor as HTMLElement
        }
      } catch {
        return null
      }
    }

    return (
      anchorElementsRef.current.find(
        (anchor) => anchor === targetElement || anchor.contains(targetElement),
      ) ?? null
    )
  }

  handleShowTooltipRef.current = (anchor: HTMLElement | null) => {
    if (!anchor) {
      return
    }
    if (!anchor.isConnected) {
      setActiveAnchor(null)
      return
    }
    if (disableTooltip?.(anchor)) {
      return
    }
    if (delayShow && activeAnchorRef.current && anchor !== activeAnchorRef.current) {
      // Moving to a different anchor while one is already active — defer the anchor
      // switch until the show delay fires to prevent content/position from updating
      // before visibility transitions complete.
      if (tooltipShowDelayTimerRef.current) {
        clearTimeout(tooltipShowDelayTimerRef.current)
      }
      tooltipShowDelayTimerRef.current = setTimeout(() => {
        setActiveAnchor(anchor)
        handleShow(true)
      }, delayShow)
    } else {
      setActiveAnchor(anchor)
      if (delayShow) {
        handleShowTooltipDelayed()
      } else {
        handleShow(true)
      }
    }

    if (tooltipHideDelayTimerRef.current) {
      clearTimeout(tooltipHideDelayTimerRef.current)
    }
  }

  handleHideTooltipRef.current = () => {
    if (clickable) {
      handleHideTooltipDelayed(delayHide || 100)
    } else if (delayHide) {
      handleHideTooltipDelayed()
    } else {
      handleShow(false)
    }

    if (tooltipShowDelayTimerRef.current) {
      clearTimeout(tooltipShowDelayTimerRef.current)
    }
  }

  // Update debounced callbacks to always delegate to latest handler refs
  const debouncedShow = debouncedShowRef.current
  const debouncedHide = debouncedHideRef.current
  debouncedShow.setCallback((anchor: HTMLElement | null) => handleShowTooltipRef.current(anchor))
  debouncedHide.setCallback(() => handleHideTooltipRef.current())

  // --- Effect 1: Delegated anchor events + tooltip hover ---
  // Only re-runs when the set of active event types or interaction mode changes.
  // Handlers read reactive values (activeAnchor, show, etc.) from refs at invocation
  // time, so this effect is decoupled from show/hide state changes.
  useEffect(() => {
    const cleanupFns: (() => void)[] = []

    const addDelegatedListener = (eventType: string, listener: (event: Event) => void) => {
      cleanupFns.push(addDelegatedEventListener(eventType, listener))
    }

    const activeAnchorContainsTarget = (event?: Event): boolean =>
      Boolean(event?.target && activeAnchorRef.current?.contains(event.target as HTMLElement))

    const debouncedHandleShowTooltip = (anchor: HTMLElement | null) => {
      debouncedHide.cancel()
      debouncedShow(anchor)
    }
    const debouncedHandleHideTooltip = () => {
      debouncedShow.cancel()
      debouncedHide()
    }

    const addDelegatedHoverOpenListener = () => {
      addDelegatedListener('mouseover', (event) => {
        const anchor = resolveAnchorElementRef.current(event.target)
        if (!anchor) {
          return
        }
        const relatedAnchor = resolveAnchorElementRef.current((event as MouseEvent).relatedTarget)
        if (relatedAnchor === anchor) {
          return
        }
        debouncedHandleShowTooltip(anchor)
      })
    }

    const addDelegatedHoverCloseListener = () => {
      addDelegatedListener('mouseout', (event) => {
        const targetAnchor = resolveAnchorElementRef.current(event.target)
        if (!targetAnchor && !activeAnchorContainsTarget(event)) {
          return
        }
        const relatedTarget = (event as MouseEvent).relatedTarget as HTMLElement | null
        const containerAnchor = targetAnchor || activeAnchorRef.current
        if (containerAnchor?.contains(relatedTarget)) {
          return
        }
        debouncedHandleHideTooltip()
      })
    }

    if (actualOpenEvents.mouseenter) {
      addDelegatedHoverOpenListener()
    }
    if (actualCloseEvents.mouseleave) {
      addDelegatedHoverCloseListener()
    }
    if (actualOpenEvents.mouseover) {
      addDelegatedHoverOpenListener()
    }
    if (actualCloseEvents.mouseout) {
      addDelegatedHoverCloseListener()
    }
    if (actualOpenEvents.focus) {
      addDelegatedListener('focusin', (event) => {
        debouncedHandleShowTooltip(resolveAnchorElementRef.current(event.target))
      })
    }
    if (actualCloseEvents.blur) {
      addDelegatedListener('focusout', (event) => {
        const targetAnchor = resolveAnchorElementRef.current(event.target)
        if (!targetAnchor && !activeAnchorContainsTarget(event)) {
          return
        }
        const relatedTarget = (event as FocusEvent).relatedTarget as HTMLElement | null
        const containerAnchor = targetAnchor || activeAnchorRef.current
        if (containerAnchor?.contains(relatedTarget)) {
          return
        }
        debouncedHandleHideTooltip()
      })
    }

    const regularEvents = ['mouseover', 'mouseout', 'mouseenter', 'mouseleave', 'focus', 'blur']
    const clickEvents = ['click', 'dblclick', 'mousedown', 'mouseup']

    const handleClickOpenTooltipAnchor = (event?: Event) => {
      const anchor = resolveAnchorElementRef.current(event?.target ?? null)
      if (!anchor) {
        return
      }
      if (showRef.current && activeAnchorRef.current === anchor) {
        return
      }
      handleShowTooltipRef.current(anchor)
    }
    const handleClickCloseTooltipAnchor = (event?: Event) => {
      if (!showRef.current || !activeAnchorContainsTarget(event)) {
        return
      }
      handleHideTooltipRef.current()
    }

    Object.entries(actualOpenEvents).forEach(([event, enabled]) => {
      if (!enabled || regularEvents.includes(event)) {
        return
      }
      if (clickEvents.includes(event)) {
        addDelegatedListener(event, handleClickOpenTooltipAnchor as (event: Event) => void)
      }
    })

    Object.entries(actualCloseEvents).forEach(([event, enabled]) => {
      if (!enabled || regularEvents.includes(event)) {
        return
      }
      if (clickEvents.includes(event)) {
        addDelegatedListener(event, handleClickCloseTooltipAnchor as (event: Event) => void)
      }
    })

    if (float) {
      addDelegatedListener('pointermove', (event) => {
        const currentActiveAnchor = activeAnchorRef.current
        if (!currentActiveAnchor) {
          return
        }
        const targetAnchor = resolveAnchorElementRef.current(event.target)
        if (targetAnchor !== currentActiveAnchor) {
          return
        }
        const mouseEvent = event as MouseEvent
        const mousePosition = {
          x: mouseEvent.clientX,
          y: mouseEvent.clientY,
        }
        handleTooltipPositionRef.current(mousePosition)
        lastFloatPosition.current = mousePosition
      })
    }

    const tooltipElement = tooltipRef.current
    const handleMouseOverTooltip = () => {
      hoveringTooltip.current = true
    }
    const handleMouseOutTooltip = () => {
      hoveringTooltip.current = false
      handleHideTooltipRef.current()
    }

    const addHoveringTooltipListeners =
      clickable && (actualCloseEvents.mouseout || actualCloseEvents.mouseleave)
    if (addHoveringTooltipListeners) {
      tooltipElement?.addEventListener('mouseover', handleMouseOverTooltip)
      tooltipElement?.addEventListener('mouseout', handleMouseOutTooltip)
    }

    return () => {
      cleanupFns.forEach((fn) => fn())
      if (addHoveringTooltipListeners) {
        tooltipElement?.removeEventListener('mouseover', handleMouseOverTooltip)
        tooltipElement?.removeEventListener('mouseout', handleMouseOutTooltip)
      }
      debouncedShow.cancel()
      debouncedHide.cancel()
    }
    // `rendered` needs to be a dependency because `tooltipRef` becomes stale when the
    // tooltip is removed from / added to the DOM.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [actualOpenEvents, actualCloseEvents, float, clickable, rendered])

  // --- Effect 2: Global close events + auto-update ---
  // Re-runs when the global close config changes, or when the active anchor changes
  // (for scroll parent listeners and floating-ui autoUpdate).
  useEffect(() => {
    const handleScrollResize = () => {
      handleShowRef.current(false)
    }

    const tooltipScrollParent = tooltipScrollParentRef.current
    const anchorScrollParent = anchorScrollParentRef.current

    if (actualGlobalCloseEvents.scroll) {
      window.addEventListener('scroll', handleScrollResize)
      anchorScrollParent?.addEventListener('scroll', handleScrollResize)
      tooltipScrollParent?.addEventListener('scroll', handleScrollResize)
    }
    let updateTooltipCleanup: null | (() => void) = null
    if (actualGlobalCloseEvents.resize) {
      window.addEventListener('resize', handleScrollResize)
    } else if (activeAnchor && tooltipRef.current) {
      updateTooltipCleanup = autoUpdate(
        activeAnchor as HTMLElement,
        tooltipRef.current as HTMLElement,
        () => updateTooltipPositionRef.current(),
        {
          ancestorResize: true,
          elementResize: true,
          layoutShift: true,
